// /frontend-react/src/components/ProfilePage.js

import React from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (Extracted from IC/Login) ---
const mockProfileData = {
    name: "LIM CHIN WEI",
    icNumber: "851020-07-5XXX",
    dateOfBirth: "20 / OCTOBER / 1985",
    address: "NO. 12, JALAN SAGA, KUALA LUMPUR",
    emergencyContact: "CHIN YEE (012-3456789)",
};

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    
    const profile = mockProfileData;

    const InfoCard = ({ title, value }) => (
        <div style={{
            padding: '15px',
            margin: '10px 0',
            backgroundColor: '#fff',
            border: '2px solid #1A73E8',
            borderRadius: '10px',
            textAlign: 'left',
            boxShadow: '0 2px 5px rgba(0,0,0,0.1)',
        }}>
            <p style={{ fontSize: isEasyMode ? '22px' : '16px', fontWeight: 'bold', margin: '0 0 5px 0', color: '#1A73E8' }}>
                {title.toUpperCase()}
            </p>
            <p style={{ fontSize: isEasyMode ? '30px' : '20px', margin: 0, color: '#333' }}>
                {value}
            </p>
        </div>
    );

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '20px 0 10px 0', color: '#333' }}>
                Personal Details
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <InfoCard title="Name" value={profile.name} />
                <InfoCard title="IC Number" value={profile.icNumber} />
                <InfoCard title="Date of Birth" value={profile.dateOfBirth} />
                <InfoCard title="Address" value={profile.address} />
                <InfoCard title="Emergency Contact" value={profile.emergencyContact} />

                <button
                    onClick={() => alert("Redirecting to Edit Profile.")}
                    style={{
                        padding: '15px 30px',
                        fontSize: isEasyMode ? '28px' : '18px',
                        backgroundColor: 'orange',
                        color: 'white',
                        border: 'none',
                        borderRadius: '8px',
                        marginTop: '30px'
                    }}
                >
                    EDIT PROFILE ✍️
                </button>
            </div>
        </div>
    );
}

export default ProfilePage;
